void normalizeRefugeOccupants() {
    if (!hasRefuge) return;
    if ((!refugeUnlocked && refugeContains(x, z, padding: .3)) ||
        vault != null) {
      x = 13;
      z = 7.7;
      y = 0;
      climb = null;
      vault = null;
      grapple = null;
      breakFreeTime = 0;
      stopInput();
    }
    for (final e in enemies) {
      if (e.alive &&
          (refugeContains(e.x, e.z, padding: e.collisionRadius) ||
              e.vault != null)) {
        final row = (map['enemies'] as List).firstWhere(
          (row) => row['id'] == e.id,
        );
        e.x = (row['x'] as num).toDouble();
        e.z = (row['z'] as num).toDouble();
        e.y = 0;
        e.vault = null;
        e.climb = null;
        e.companionTarget = null;
        e.attackPending = e.grabPending = false;
        e.windup = 0;
        if (grapple?.enemyId == e.id) {
          grapple = null;
          breakFreeTime = 0;
        }
      }
    }
    refreshRefuge();
  }
}

void _finishEvent() {
    final id = director!.id;
    if (id == 'title_call') {
      director = null;
      state!
        ..stopInput()
        ..phase = PlayPhase.playing;
      if (_openingAfterTitle) startEvent('opening');
      _openingAfterTitle = false;
      return;
    }
    state!.seenEvents.add(id);
    state!
      ..stopInput()
      ..phase = id == 'ending' ? PlayPhase.clear : PlayPhase.playing;
    director = null;
    // Restore any temporary ending positions and normally absent actors.
    for (final entry in npcs.entries) {
      final rows = state!.npcs.where((n) => n['id'] == entry.key);
      entry.value.node.visible = rows.isNotEmpty;
      if (rows.isNotEmpty) {
        entry.value.node.position = vm.Vector3(
          (rows.first['x'] as num).toDouble(),
          0,
          (rows.first['z'] as num).toDouble(),
        );
      }
    }
    if (id == 'ending' && state!.refugeComplete) unawaited(saveCheckpoint());
    if (id != 'ending') {
      state!.invulnerable = 1;
      state!.say(state!.objective);
      unawaited(saveCheckpoint());
    }
  }

